import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])
    K = int(input_data[2])
    S = input_data[3]
    T = input_data[4]

    def dist(c1, c2):
        d = abs(ord(c1) - ord(c2))
        return min(d, 26 - d)

    costs = []
    for i in range(M):
        c = 0
        for j in range(N):
            if i + j >= M:
                break
            c += dist(S[j], T[i + j])
        costs.append(c)

    dp = [float('inf')] * (K + 1)
    dp[0] = 0

    for i in range(M):
        new_dp = list(dp)
        for k in range(K + 1):
            if dp[k] == float('inf'):
                continue
            current_cost = costs[i]
            if k + current_cost <= K:
                new_dp[k + current_cost] = max(new_dp[k + current_cost], dp[k] + 1)
        dp = new_dp

    ans = 0
    for k in range(K + 1):
        if dp[k] != float('inf'):
            ans = max(ans, dp[k])

    print(ans)

solve()
